package dev.eugheist.ttmodern;
final class AdvancedToolMiningAudit {
 static void check(boolean ok,String label){if(!ok)throw new IllegalStateException("TT advanced mining: "+label);}
 static void run(net.minecraft.server.MinecraftServer server){var level=server.overworld();var p=new net.neoforged.neoforge.common.util.FakePlayer(level,new com.mojang.authlib.GameProfile(java.util.UUID.randomUUID(),"MiningAudit"));p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new net.minecraft.world.item.ItemStack(KamiTools.PICK.get()));var origin=new net.minecraft.core.BlockPos(5,290,5);p.setPos(5.5,290,3);var bounds=AdvancedToolModes.pick(1,net.minecraft.core.Direction.UP);var saved=new java.util.HashMap<net.minecraft.core.BlockPos,net.minecraft.world.level.block.state.BlockState>();for(var pos:bounds.positions(origin)){saved.put(pos,level.getBlockState(pos));level.setBlock(pos,net.minecraft.world.level.block.Blocks.STONE.defaultBlockState(),2);}saved.put(origin,level.getBlockState(origin));level.setBlock(origin,net.minecraft.world.level.block.Blocks.STONE.defaultBlockState(),2);var protectedPos=origin.offset(1,0,0);var wood=origin.offset(-1,0,0);var hard=origin.offset(0,0,1);level.setBlock(wood,net.minecraft.world.level.block.Blocks.OAK_LOG.defaultBlockState(),2);level.setBlock(hard,net.minecraft.world.level.block.Blocks.OBSIDIAN.defaultBlockState(),2);
 java.util.function.Consumer<net.neoforged.neoforge.event.level.BlockEvent.BreakEvent> deny=e->{if(e.getPlayer()==p&&e.getPos().equals(protectedPos))e.setCanceled(true);};net.neoforged.neoforge.common.NeoForge.EVENT_BUS.addListener(deny);
 try{AdvancedToolMining.harvest(p,origin,bounds,s->s.is(net.minecraft.tags.BlockTags.MINEABLE_WITH_PICKAXE));check(level.getBlockState(origin).is(net.minecraft.world.level.block.Blocks.STONE),"center left for ordinary mining");check(level.getBlockState(protectedPos).is(net.minecraft.world.level.block.Blocks.STONE),"native canceled break protected");check(level.getBlockState(wood).is(net.minecraft.world.level.block.Blocks.OAK_LOG),"wrong material untouched");check(level.getBlockState(hard).is(net.minecraft.world.level.block.Blocks.OBSIDIAN),"original strength ratio excludes too-hard block");long removed=bounds.positions(origin).stream().filter(pos->level.getBlockState(pos).isAir()).count();check(removed==21,"exact native extra break count "+removed);var drops=level.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new net.minecraft.world.phys.AABB(p.getX()-1,p.getY(),p.getZ()-1,p.getX()+1,p.getY()+2,p.getZ()+1));check(drops.stream().filter(e->e.getItem().is(net.minecraft.world.item.Items.COBBLESTONE)).mapToInt(e->e.getItem().getCount()).sum()==21,"ordinary native loot moved to player: "+drops.stream().map(e->e.getItem()+"@"+e.position()).toList());for(var item:drops)item.discard();for(var at:bounds.positions(origin))if(level.getBlockState(at).isAir())level.setBlock(at,net.minecraft.world.level.block.Blocks.STONE.defaultBlockState(),2);p.getMainHandItem().enchant(server.registryAccess().registryOrThrow(net.minecraft.core.registries.Registries.ENCHANTMENT).getHolderOrThrow(net.minecraft.world.item.enchantment.Enchantments.SILK_TOUCH),1);AdvancedToolMining.harvest(p,origin,bounds,s->s.is(net.minecraft.tags.BlockTags.MINEABLE_WITH_PICKAXE));var silkDrops=level.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new net.minecraft.world.phys.AABB(p.getX()-1,p.getY(),p.getZ()-1,p.getX()+1,p.getY()+2,p.getZ()+1));check(silkDrops.stream().filter(e->e.getItem().is(net.minecraft.world.item.Items.STONE)).mapToInt(e->e.getItem().getCount()).sum()==21,"native silk touch applies to every extra block");check(!AdvancedToolMining.breaking(p),"recursion guard released");System.out.println("TT ADVANCED TOOL MINING AUDIT: ALL PASS (native 21block harvest/drop collection/silk touch,center exclusion,canceled protection,material filter,hardness ratio,guard cleanup)");
 }finally{net.neoforged.neoforge.common.NeoForge.EVENT_BUS.unregister(deny);for(var item:level.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new net.minecraft.world.phys.AABB(0,288,0,10,294,10)))item.discard();saved.forEach((pos,state)->level.setBlock(pos,state,2));p.discard();}
 }
}
